#!/usr/bin/env python3
"""Configure this decompilation project (generated by romwright new-project).

    python3 configure.py              fetch tools, split the image, write build.ninja + objdiff.json
    python3 configure.py swap NAME    switch one function from assembly to a C unit (see README.md)
    ninja                             build, link and check the image against the retail sha1
    ninja progress                    objdiff report (build/report.json)

Tools come from `config/toolchain.json`, a pinned manifest (url + sha256 per
tool) that `tools/download_tool.py` fetches into build/tools/ and verifies. A
toolchain profile (`--toolchain FILE`, or config/toolchain.local.json) replaces
any tool with one you already have installed.
"""
import argparse
import hashlib
import json
import os
import platform
import re
import shlex
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT / "tools"))
import toolchain  # noqa: E402
from toolchain import PROJECT, BUILD, quote  # noqa: E402

NAME = PROJECT["image"]["file"]
YAML = ROOT / PROJECT["splat"]["yaml"]
STATEMENT = re.compile(r"^(\s*)(build/\S+?\.o)\((\.\w+)\);\s*$")


def resolve_tools(args):
    return toolchain.resolve_tools(args)


# --------------------------------------------------------------------------
# splat
# --------------------------------------------------------------------------

def sha1_file(path):
    return hashlib.sha1(Path(path).read_bytes()).hexdigest()


def snapshot(roots):
    """path -> (mtime_ns, sha1) of every file below `roots`."""
    state = {}
    for base in roots:
        for path in (ROOT / base).rglob("*"):
            if path.is_file():
                state[path] = (path.stat().st_mtime_ns, hashlib.sha1(path.read_bytes()).hexdigest())
    return state


def restore_unchanged(before):
    """splat rewrites every file it writes; give the ones whose bytes did not
    change their old modification time back, so ninja rebuilds only what did."""
    for path, (mtime, digest) in before.items():
        if path.exists() and hashlib.sha1(path.read_bytes()).hexdigest() == digest:
            os.utime(path, ns=(mtime, mtime))


def split(force):
    original = ROOT / PROJECT["image"]["orig"]
    if not original.exists():
        raise SystemExit(f"{original}: the retail image is missing; copy your own dump there")
    if sha1_file(original) != PROJECT["image"]["sha1"]:
        raise SystemExit(
            f"{original}: sha1 {sha1_file(original)} is not the {PROJECT['image']['sha1']} this project was generated from"
        )
    stamp_text = hashlib.sha1(
        b"\0".join(Path(p).read_bytes() for p in (YAML, ROOT / "config" / "symbol_addrs.txt"))
        + PROJECT["image"]["sha1"].encode()
    ).hexdigest()
    stamp = BUILD / ".split-stamp"
    ld = ROOT / f"{NAME}.ld"
    if not force and ld.exists() and stamp.exists() and stamp.read_text() == stamp_text:
        return
    try:
        import splat  # noqa: F401
    except ImportError:
        raise SystemExit("splat is not installed: python3 -m pip install -r requirements.txt")
    try:
        from importlib.metadata import version
        pinned = PROJECT["splat"]["version"]
        if version("splat64") != pinned:
            print(f"warning: splat64 {version('splat64')} installed, this project was generated for {pinned}", file=sys.stderr)
    except Exception:
        pass
    print(f"splat split {YAML.relative_to(ROOT)}  (this takes a while on a large image)", flush=True)
    before = snapshot(["asm", "assets"])
    subprocess.run([sys.executable, "-m", "splat", "split", str(YAML.relative_to(ROOT))], cwd=ROOT, check=True)
    restore_unchanged(before)
    BUILD.mkdir(exist_ok=True)
    stamp.write_text(stamp_text)


def unit_slots():
    """C units of the splat config -> the size of the slot each owns.

    A slot runs from the unit's first byte to the next subsegment (or the end
    of the segment): the function plus the padding the retail linker left
    after it. Offsets are relative to the start of the segment, which is where
    the linker's output section starts."""
    import yaml
    config = yaml.safe_load(YAML.read_text())
    slots = {}
    segments = config["segments"]
    for index, segment in enumerate(segments):
        if not isinstance(segment, dict) or segment.get("type") != "code":
            continue
        following = segments[index + 1] if index + 1 < len(segments) else None
        end = following[0] if isinstance(following, list) else (following or {}).get("start")
        entries = segment.get("subsegments", [])
        for i, entry in enumerate(entries):
            if entry[1] not in ("c", "cpp"):
                continue
            stop = entries[i + 1][0] if i + 1 < len(entries) else end
            slots[entry[2]] = stop - segment["start"]
    return slots


def fast_link_script(ld_text, slots):
    """Rewrite splat's linker script for speed and for C units.

    Speed: splat lists every object as its own `file(.section)` statement;
    GNU ld searches the input files once per statement, which is cubic on a
    split this fine (a 4000-function image links in minutes instead of
    seconds). Runs of objects that share a directory collapse to one wildcard
    statement; objects are handed to ld on the command line in the original
    order, which is the order the wildcard visits them in. Objects left alone
    in their directory are named by a path-suffix wildcard instead of exactly.

    C units: only their `.text` is linked (their literals and data are retail
    bytes already, in the binary segments), and the location counter is moved
    to the end of the unit's slot, so the compiler's padding (or lack of it)
    cannot move anything after it. A unit longer than its slot makes ld stop
    with "cannot move location counter backwards", which is the right answer."""
    lines = []
    for line in ld_text.split("\n"):
        m = STATEMENT.match(line)
        if m and m.group(2).startswith("build/src/"):
            if m.group(3) != ".text":
                continue
            lines.append(line)
            name = m.group(2)[len("build/src/"):].rsplit(".", 2)[0]
            if name in slots:
                lines.append(f"{m.group(1)}. = {slots[name]:#x};")
            continue
        lines.append(line)
    statements = [(i, m.group(1), m.group(2), m.group(3)) for i, l in enumerate(lines) if (m := STATEMENT.match(l))]
    objects, seen = [], set()
    for _, _, path, _ in statements:
        if path not in seen:
            seen.add(path)
            objects.append(path)
    runs = []
    for item in statements:
        index, _, path, section = item
        directory = os.path.dirname(path)
        if runs and runs[-1]["dir"] == directory and runs[-1]["sec"] == section and runs[-1]["last"] == index - 1:
            runs[-1]["items"].append(item)
            runs[-1]["last"] = index
        else:
            runs.append({"dir": directory, "sec": section, "items": [item], "last": index})
    uses = {}
    for run in runs:
        uses[(run["dir"], run["sec"])] = uses.get((run["dir"], run["sec"]), 0) + 1
    drop = set()
    for run in runs:
        if uses[(run["dir"], run["sec"])] == 1 and len(run["items"]) >= 4 and not run["dir"].startswith("build/src"):
            first = run["items"][0]
            lines[first[0]] = f"{first[1]}{run['dir']}/*.o({run['sec']});"
            drop.update(item[0] for item in run["items"][1:])
    # A statement that names one exact file costs ld a scan of every input file
    # per statement; the same file named by a path suffix is a wildcard match
    # (a 13k-object link: 205 s with 95 exact statements, 20 s without).
    kept = []
    for i, line in enumerate(lines):
        if i in drop:
            continue
        m = STATEMENT.match(line)
        if m and "*" not in m.group(2):
            line = f"{m.group(1)}*{m.group(2)[len('build/'):]}({m.group(3)});"
        kept.append(line)
    return "\n".join(kept), objects


# --------------------------------------------------------------------------
# build.ninja / objdiff.json
# --------------------------------------------------------------------------

def esc(path):
    return str(path).replace("$", "$$").replace(" ", "$ ").replace(":", "$:")


class Ninja:
    def __init__(self, handle):
        self.out = handle

    def var(self, key, value):
        self.out.write(f"{key} = {value}\n")

    def rule(self, name, command, description, **extra):
        self.out.write(f"rule {name}\n  command = {command}\n  description = {description}\n")
        for key, value in extra.items():
            self.out.write(f"  {key} = {value}\n")
        self.out.write("\n")

    def build(self, outputs, rule, inputs=(), implicit=(), variables=None):
        line = f"build {' '.join(esc(o) for o in outputs)}: {rule} {' '.join(esc(i) for i in inputs)}"
        if implicit:
            line += " | " + " ".join(esc(i) for i in implicit)
        self.out.write(line + "\n")
        for key, value in (variables or {}).items():
            self.out.write(f"  {key} = {value}\n")
        self.out.write("\n")


def ld_emulation(ld):
    """`-m` for GNU ld: a multi-target MIPS ld (distribution binutils) defaults to
    64-bit big-endian and needs `elf32btsmip` / `elf32ltsmip`; the decompals ld has
    one emulation and takes `-EB` / `-EL`."""
    try:
        text = subprocess.run([ld, "--help"], capture_output=True, text=True).stdout
    except OSError:
        return []
    name = "elf32btsmip" if PROJECT["link"]["endian"] == "EB" else "elf32ltsmip"
    return ["-m", name] if name in text else []


def write_build(tools, objects):
    asflags = PROJECT["compiler"]["asflags"]
    with open(ROOT / "build.ninja", "w") as handle:
        n = Ninja(handle)
        n.var("ninja_required_version", "1.7")
        n.var("python", shlex.quote(sys.executable))
        n.out.write("\n")
        # Compilers write temporary files; /tmp may be small, quota-limited or
        # sandboxed, so they get a directory inside the project.
        (BUILD / "tmp").mkdir(parents=True, exist_ok=True)
        n.rule("as", f"$python tools/asm.py {shlex.quote(tools.need('as'))} $out $in", "as $in")
        n.rule("cc", "$python tools/cc.py $in $out", "cc $in")
        # The object list goes through a response file: thousands of paths exceed
        # the single-argument limit of a shell command line.
        ld_flags = " ".join(ld_emulation(tools.need("ld")))
        n.rule("ld", f"{shlex.quote(tools.need('ld'))} {ld_flags} --no-warn-rwx-segments -{PROJECT['link']['endian']} -T {NAME}.fast.ld "
                     f"-T config/undefined_syms.txt -T undefined_syms_auto.txt -T undefined_funcs_auto.txt --no-check-sections -o $out @$out.rsp",
               "link $out", rspfile="$out.rsp", rspfile_content="$in")
        n.rule("objcopy", f"{shlex.quote(tools.need('objcopy'))} -O binary $in $out", "image $out")
        n.rule("verify", "$python tools/verify.py $in config/checksum.sha1 $out", "verify $in")
        n.rule("report", f"{shlex.quote(tools.paths.get('objdiff-cli', 'objdiff-cli'))} report generate -o $out", "report")
        sources = {}
        for path in objects:
            src = path[len("build/"):-2]
            sources[path] = src
            if src.endswith(".s"):
                n.build([path], "as", [src], implicit=["tools/asm.py", "config/project.json"])
            else:
                n.build([path], "cc", [src], implicit=headers())
        n.build([f"build/{NAME}.elf"], "ld", objects, implicit=[f"{NAME}.fast.ld", "config/undefined_syms.txt", "undefined_syms_auto.txt", "undefined_funcs_auto.txt"])
        post = PROJECT.get("post")
        if post == "n64crc":
            # The header's CRC1/CRC2 cover the first megabyte after the boot code; a C unit changes
            # them, so they are recomputed (a no-op while the image is still all assembly).
            n.rule("crc", "$python tools/n64crc.py fix $in $out", "n64 checksum $out")
            n.build([f"build/{NAME}.raw"], "objcopy", [f"build/{NAME}.elf"])
            n.build([f"build/{NAME}"], "crc", [f"build/{NAME}.raw"], implicit=["tools/n64crc.py", "config/project.json"])
        else:
            n.build([f"build/{NAME}"], "objcopy", [f"build/{NAME}.elf"])
        n.build([f"build/{NAME}.ok"], "verify", [f"build/{NAME}"], implicit=["config/checksum.sha1"])
        # Target objects for objdiff: the retail bytes of each C unit's functions, as assembly.
        units = c_units(objects)
        for unit in units:
            if unit["target_sources"]:
                n.build([unit["target"]], "as", unit["target_sources"], implicit=["tools/asm.py", "config/project.json"])
        if "objdiff-cli" in tools.paths:
            n.build(["build/report.json"], "report", [], implicit=[u["base"] for u in units] + [u["target"] for u in units if u["target_sources"]] + ["objdiff.json"])
            n.build(["progress"], "phony", ["build/report.json"])
        n.build(["all"], "phony", [f"build/{NAME}.ok"])
        n.out.write("default all\n")
    return units


def headers():
    include = ROOT / "include"
    return sorted(str(p.relative_to(ROOT)) for p in include.rglob("*.h")) if include.exists() else []


def c_units(objects):
    """The units compiled from C, with the retail assembly objdiff compares them to."""
    units = []
    for path in objects:
        src = path[len("build/"):-2]
        if not src.startswith("src/") or src.endswith(".s"):
            continue
        rel = src[len("src/"):].rsplit(".", 1)[0]
        nonmatching = ROOT / "asm" / "nonmatchings" / rel
        files = sorted(str(p.relative_to(ROOT)) for p in nonmatching.rglob("*.s")) if nonmatching.exists() else []
        units.append({"name": rel, "source": src, "base": path, "target": f"build/target/{rel}.o", "target_sources": files})
    return units


def write_objdiff(units):
    rows = []
    for unit in units:
        row = {
            "name": unit["name"],
            "base_path": unit["base"],
            "metadata": {"complete": False, "auto_generated": False, "source_path": unit["source"]},
        }
        if unit["target_sources"]:
            row["target_path"] = unit["target"]
        rows.append(row)
    document = {
        "min_version": "2.0.0-beta.5",
        "custom_make": "ninja",
        "build_target": True,
        "build_base": True,
        "watch_patterns": ["src/**/*.c", "src/**/*.cpp", "include/**/*.h", "config/**"],
        "units": rows,
    }
    (ROOT / "objdiff.json").write_text(json.dumps(document, indent=2) + "\n")


# --------------------------------------------------------------------------
# swap
# --------------------------------------------------------------------------

def swap(args):
    text = YAML.read_text()
    target = args.function
    if re.fullmatch(r"0x[0-9a-fA-F]+", target):
        vaddr = int(target, 16)
        for seg in PROJECT["layout"]:
            if seg["vaddr"] <= vaddr < seg["vaddr"] + seg["size"]:
                target = f"{seg['offset'] + vaddr - seg['vaddr']:#x}"
        pattern = re.compile(rf"^(\s*- \[{re.escape(target)}, )asm(, ([^\]]+)\])", re.M | re.I)
    else:
        pattern = re.compile(rf"^(\s*- \[0x[0-9a-fA-F]+, )asm(, ((?:[^\]]*/)?{re.escape(target)})\])", re.M)
    match = pattern.search(text)
    if not match:
        raise SystemExit(f"`{args.function}` is not an assembly entry of {YAML.relative_to(ROOT)} (already a C unit?)")
    unit = match.group(3)
    text = pattern.sub(r"\1c\2", text, count=1)
    YAML.write_text(split_chunk_after(text, unit))
    print(f"{unit}: assembly -> C unit src/{unit}.c")
    return unit


ENTRY = re.compile(r"^(\s*- \[0x[0-9a-fA-F]+, )(\w+)(, )([^\]]+)(\])$")


def split_chunk_after(text, unit):
    """Keep every object directory one contiguous run in the link order.

    `fast_link_script` turns a directory's objects into one wildcard statement,
    which only works while nothing else sits between them. A C unit swapped out
    of the middle of a directory would cut it in two, so the entries after it
    move to a new directory (their `.s` files are rewritten there; only those
    objects rebuild)."""
    lines = text.split("\n")
    directory = os.path.dirname(unit)
    index = next((i for i, l in enumerate(lines) if (m := ENTRY.match(l)) and m.group(4) == unit), None)
    if index is None:
        return text
    used = {os.path.dirname(m.group(4)) for l in lines if (m := ENTRY.match(l))}
    n = 2
    while f"{directory}_{n}" in used:
        n += 1
    for i in range(index + 1, len(lines)):
        m = ENTRY.match(lines[i])
        if not m or os.path.dirname(m.group(4)) != directory:
            break
        lines[i] = f"{m.group(1)}{m.group(2)}{m.group(3)}{directory}_{n}/{os.path.basename(m.group(4))}{m.group(5)}"
    return "\n".join(lines)


def install_unit_source(unit, src):
    """After splat has written its `INCLUDE_ASM` stub (and the retail assembly
    objdiff compares against, under asm/nonmatchings/), put the unit's C in place."""
    destination = ROOT / "src" / f"{unit}.c"
    destination.parent.mkdir(parents=True, exist_ok=True)
    if src:
        shutil.copyfile(src, destination)
    else:
        reference = ROOT / "decompiled" / f"{Path(unit).name}.c"
        body = reference.read_text() if reference.exists() else "/* write the C for this function; it must assemble to exactly the retail bytes */\n"
        destination.write_text('#include "romwright_types.h"\n\n' + body)


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--toolchain", help="toolchain profile JSON (replaces manifest tools one by one)")
    parser.add_argument("--manifest", help="tool manifest (default config/toolchain.json)")
    parser.add_argument("--no-tools", action="store_true", help="do not download; use what is already in build/tools")
    parser.add_argument("--no-split", action="store_true", help="skip splat even if the config changed")
    parser.add_argument("--force-split", action="store_true")
    sub = parser.add_subparsers(dest="command")
    swap_parser = sub.add_parser("swap", help="turn one assembly function into a C unit")
    swap_parser.add_argument("function", help="function name or 0xADDRESS")
    swap_parser.add_argument("--src", help="C file to install as the unit")
    args = parser.parse_args()
    swapped = None
    if args.command == "swap":
        swapped = swap(args)
        args.force_split = True
    tools = resolve_tools(args)
    if not args.no_split:
        split(args.force_split)
    if swapped:
        install_unit_source(swapped, args.src)
    ld_text = (ROOT / f"{NAME}.ld").read_text()
    fast, objects = fast_link_script(ld_text, unit_slots() if any("/src/" in o or o.startswith("build/src/") for o in re.findall(r"(build/\S+?\.o)\(", ld_text)) else {})
    (ROOT / f"{NAME}.fast.ld").write_text(fast)
    units = write_build(tools, objects)
    write_objdiff(units)
    print(f"configured: {len(objects)} objects, {len(units)} C unit(s); run `ninja`")


if __name__ == "__main__":
    main()
